#[tokio::test]
async fn connected_catalog_retains_returned_ids_and_credentials() {
    let server = MockServer::start().await;
    for (verb, endpoint, fixture, status) in [
        (
            "POST",
            "/v2/products",
            include_str!("fixtures/sdk_create_product_response_value_201_application_json.json"),
            201,
        ),
        (
            "GET",
            "/v2/products/120",
            include_str!("fixtures/sdk_get_product_response_value_200_application_json.json"),
            200,
        ),
        (
            "PATCH",
            "/v2/products/120",
            include_str!("fixtures/sdk_update_product_response_value_200_application_json.json"),
            200,
        ),
    ] {
        let mut value: serde_json::Value = serde_json::from_str(fixture).unwrap();
        value["data"]["id"] = serde_json::json!(120);
        value["data"]["title"] = serde_json::json!(if verb == "PATCH" {
            "Design kit revised"
        } else {
            "Design kit"
        });
        Mock::given(method(verb))
            .and(path(endpoint))
            .respond_with(ResponseTemplate::new(status).set_body_json(value))
            .mount(&server)
            .await;
    }
    let client = Client::new("catalog_key", "launch-lab")
        .with_base_url(server.uri())
        .with_max_retries(0);
    assert_eq!(catalog::catalog_workflow(&client).await.unwrap(), 120);
    let other = Client::new("other_key", "other-store")
        .with_base_url(server.uri())
        .with_max_retries(0);
    other
        .products()
        .get("120", Default::default())
        .await
        .unwrap();
    client
        .products()
        .get("120", Default::default())
        .await
        .unwrap();
    let requests = server.received_requests().await.unwrap();
    assert_eq!(requests.len(), 5);
    for (index, request) in requests.iter().enumerate() {
        assert_eq!(
            request.headers.get("authorization").unwrap(),
            if index == 3 {
                "Bearer other_key"
            } else {
                "Bearer catalog_key"
            }
        );
        assert_eq!(
            request.headers.get("x-store").unwrap(),
            if index == 3 {
                "other-store"
            } else {
                "launch-lab"
            }
        );
    }
    assert_eq!(
        requests[0].body_json::<serde_json::Value>().unwrap()["title"],
        "Design kit"
    );
    assert_eq!(
        requests[2].body_json::<serde_json::Value>().unwrap()["title"],
        "Design kit revised"
    );
}

