#[tokio::test]
async fn exact_documented_examples() {
    let server = MockServer::start().await;
    let client = Client::new("test_key", "test_store")
        .with_base_url(server.uri())
        .with_max_retries(0);
    Mock::given(method("GET"))
        .and(path("/v2/products"))
        .and(header("Authorization", "Bearer test_key"))
        .and(header("X-STORE", "test_store"))
        .and(query_param("limit", "1"))
        .respond_with(ResponseTemplate::new(200).set_body_json(page(1, 1)))
        .expect(1)
        .mount(&server)
        .await;
    assert_eq!(
        first_request::first_request(&client).await.unwrap(),
        vec![(101, "Example product".to_owned())]
    );
    server.verify().await;
    server.reset().await;
    for number in 1..=3 {
        Mock::given(method("GET"))
            .and(path("/v2/products"))
            .and(query_param("page", number.to_string()))
            .and(query_param("limit", "15"))
            .respond_with(ResponseTemplate::new(200).set_body_json(page(number, 3)))
            .expect(1)
            .mount(&server)
            .await;
    }
    assert_eq!(
        pagination::paginate(&client).await.unwrap(),
        vec![
            (101, "Example product".to_owned()),
            (101, "Example product".to_owned())
        ]
    );
    server.verify().await;
    server.reset().await;
    Mock::given(method("GET"))
        .and(path("/v2/products"))
        .respond_with(ResponseTemplate::new(401).set_body_json(
            serde_json::json!({"message":"Invalid key", "request_id":"req_example"}),
        ))
        .expect(1)
        .mount(&server)
        .await;
    assert_eq!(
        errors::handle_error(&client).await.unwrap(),
        "API status 401: Invalid key (request req_example)"
    );
    server.verify().await;
}
